/****************************************************************************
 * Name: up_irq_enable
 *
 * Description:
 *   Enable interrupts by setting the MIE bit in the mstatus CSR.
 *   This function returns the previous interrupt state so it can be
 *   restored later.
 *
 * Returned Value:
 *   The previous interrupt state (mstatus value before enabling)
 *
 ****************************************************************************/

irqstate_t up_irq_enable(void)
{
  irqstate_t flags;

  /* Read current mstatus */

  flags = READ_CSR(mstatus);

  /* Set MIE bit to enable interrupts */

  SET_CSR(mstatus, MSTATUS_MIE);

  return flags;
}

